    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>একটি language model ৪০০ শব্দের একটি বাক্যের সম্ভাব্যতা হিসাব করছে: প্রতিটি শব্দের সম্ভাব্যতা প্রায় ০.১, আর সবগুলো গুণ। ০.১⁴⁰⁰ = ১০⁻⁴⁰⁰—কম্পিউটারের সবচেয়ে ছোট সংখ্যার চেয়েও ছোট, ফল আসে ঠিক ০। তাহলে দুটি বাক্যের তুলনা করা যাবে কীভাবে?</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>log-এর মূল নিয়ম ব্যবহার করে গুণফলকে যোগফলে রূপান্তর করতে পারবেন</li><li>underflow কী এবং log কীভাবে তা আটকায় দেখাতে পারবেন</li><li>derivative-কে ঢাল হিসেবে ব্যাখ্যা করে সংখ্যাগতভাবে হিসাব করতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 40 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/probability/">সম্ভাব্যতা, শর্তসাপেক্ষ সম্ভাব্যতা ও Distribution</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>লগারিদম</strong> (<em lang="en">logarithm</em>): log_b(x) = y মানে bʸ = x। এই কোর্সে log মানে প্রাকৃতিক log (ভিত্তি e ≈ ২.৭১৮), JavaScript-এ <code>Math.log</code>।</p><div class="wgba-table-wrap"><table><caption>log-এর দরকারি নিয়ম</caption><thead><tr><th scope="col">নিয়ম</th><th scope="col">উদাহরণ</th></tr></thead><tbody><tr><td>log(a × b) = log a + log b</td><td>log(০.১ × ০.২) = log ০.১ + log ০.২</td></tr><tr><td>log(১) = ০</td><td>নিশ্চিত ঘটনার log শূন্য</td></tr><tr><td>০ < p < ১ হলে log p < ০</td><td>log ০.৫ ≈ −০.৬৯৩</td></tr><tr><td>log একঘেয়ে বর্ধমান</td><td>a > b হলে log a > log b—তুলনার ক্রম বদলায় না</td></tr></tbody></table></div><p><strong>আন্ডারফ্লো</strong> (<em lang="en">underflow</em>): খুব ছোট সংখ্যা ০ হয়ে যাওয়া। JavaScript-এর সংখ্যা প্রায় ১০⁻³⁰⁸-এর নিচে (subnormal ধরলে ~৫×১০⁻³²⁴) যেতে পারে না। ৪০০ বার log ০.১ যোগ = ৪০০ × (−২.৩০২৬) ≈ −৯২১—কোনো সমস্যা নেই।</p><p><strong>−log p কে “বিস্ময়” ভাবুন:</strong> p = ১ হলে ০ (কোনো বিস্ময় নেই), p ছোট হলে বড়। অধ্যায় ৪ ও ৯-এর cross-entropy loss ঠিক এটি।</p><p><strong>ডেরিভেটিভ</strong> (<em lang="en">derivative</em>): f′(x) = x-এর খুব কাছে f কত দ্রুত বদলায়—graph-এর ঐ বিন্দুতে স্পর্শকের ঢাল।</p><p><strong>সংখ্যাগত অনুমান (central difference):</strong> f′(x) ≈ [f(x + h) − f(x − h)] / (২h), যেখানে h ছোট (যেমন ০.০০০১)।</p><div class="wgba-table-wrap"><table><caption>তিনটি পরিচিত derivative</caption><thead><tr><th scope="col">f(x)</th><th scope="col">f′(x)</th><th scope="col">x = ৩-এ</th></tr></thead><tbody><tr><td>x²</td><td>২x</td><td>৬</td></tr><tr><td>৫x + ২</td><td>৫</td><td>৫</td></tr><tr><td>log x</td><td>১/x</td><td>০.৩৩৩</td></tr></tbody></table></div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> Derivative হলো গাড়ির স্পিডোমিটার: মোট দূরত্ব নয়, এই মুহূর্তে কত দ্রুত দূরত্ব বাড়ছে। log হলো ভূমিকম্পের রিখটার স্কেল—বিশাল পরিসরকে সামলানোর মতো সংখ্যায় আনে।</p><p><strong>কোথায় ভাঙে:</strong> স্পিডোমিটার সরাসরি মাপে; সংখ্যাগত derivative একটি অনুমান, যার ভুল h-এর মানের ওপর নির্ভর করে—h খুব বড় হলে ঢাল ভুল, খুব ছোট হলে কম্পিউটারের দশমিক-ত্রুটি বাড়ে।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p><strong>log:</strong> তিনটি শব্দের সম্ভাব্যতা ০.৫, ০.২, ০.১।</p><ol><li>গুণফল = ০.০১।</li><li>log যোগফল = log ০.৫ + log ০.২ + log ০.১ ≈ −০.৬৯৩১ − ১.৬০৯৪ − ২.৩০২৬ = −৪.৬০৫২।</li><li>যাচাই: log ০.০১ ≈ −৪.৬০৫২ ✓।</li></ol><p><strong>Derivative:</strong> f(x) = x², x = ৩, h = ০.০০০১।</p><ol><li>f(৩.০০০১) = ৯.০০০৬০০০১, f(২.৯৯৯৯) = ৮.৯৯৯৪০০০১।</li><li>পার্থক্য = ০.০০১২; ÷ (২ × ০.০০০১) = ৬.০০০।</li><li>সূত্র ২x = ৬ ✓।</li></ol></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><div class="wgba-note">কোডে underflow নিজের চোখে দেখব, তারপর একটি সাধারণ numericDerivative ফাংশন যেকোনো f-এ চালাব।</div><h3>underflow, log-যোগ ও সংখ্যাগত derivative</h3><div class="wgba-playground-slot" data-exercise="ex-les-03-06-logs-derivatives-1"><pre class="wgba-code"><code>// ১) underflow
let product = 1, logSum = 0;
for (let i = 0; i &lt; 400; i++) { product *= 0.1; logSum += Math.log(0.1); }
console.log(&quot;গুণফল:&quot;, product, &quot;| log-যোগ:&quot;, Math.round(logSum * 100) / 100);

// ২) log গুণকে যোগে বদলায়
const ps = [0.5, 0.2, 0.1];
const r4 = (x) =&gt; Math.round(x * 10000) / 10000;
console.log(&quot;log(গুণফল) =&quot;, r4(Math.log(ps.reduce((a, b) =&gt; a * b, 1))), &quot; log-যোগ =&quot;, r4(ps.reduce((s, p) =&gt; s + Math.log(p), 0)));
console.log(&quot;বিস্ময় −log p:&quot;, ps.map((p) =&gt; r4(-Math.log(p))));

// ৩) সংখ্যাগত derivative
const numericDerivative = (f, x, h = 1e-4) =&gt; (f(x + h) - f(x - h)) / (2 * h);
const tests = [
  [&quot;x^2&quot;, (x) =&gt; x * x, (x) =&gt; 2 * x],
  [&quot;5x+2&quot;, (x) =&gt; 5 * x + 2, () =&gt; 5],
  [&quot;log x&quot;, (x) =&gt; Math.log(x), (x) =&gt; 1 / x],
];
for (const [name, f, exact] of tests) {
  console.log(name, &quot;x=3: সংখ্যাগত&quot;, r4(numericDerivative(f, 3)), &quot;সূত্র&quot;, r4(exact(3)));
}</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>product *= 0.1</code> ৪০০ বার: ~৩২৪ বারের পর ফল ঠিক ০ হয়ে যায়—এরপর আর কোনো তথ্য থাকে না।</li><li><code>logSum += Math.log(0.1)</code>: প্রতিবার −২.৩০২৬ যোগ; শেষে −৯২১.০৩।</li><li><code>(f, x, h = 1e-4) =></code>: h-এর default মান ০.০০০১; চাইলে তৃতীয় argument দিয়ে বদলানো যায়।</li><li><code>for (const [name, f, exact] of tests)</code>: প্রতিটি পরীক্ষা [নাম, function, সূত্র-derivative]।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>সংখ্যাগত derivative সূত্র না জানলেও কাজ করে—তাই এটি “gradient check” হিসেবে পরে ব্যবহার করব: neural network-এর হাতে-লেখা gradient সঠিক কিনা যাচাই করতে (অধ্যায় ৫)।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>log(ab) = log a + log b</li><li>অনেক সম্ভাব্যতা গুণ নয়, log যোগ করুন</li><li>−log p: ছোট p-তে বড় “বিস্ময়”</li><li>derivative = ঢাল; central difference দিয়ে যাচাই</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>derivative-এর সীমা (limit) সংজ্ঞা</li><li>সব derivative নিয়ম মুখস্থ</li><li>ভিন্ন ভিত্তির log রূপান্তর</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>f(x) = (x − ২)² নিন। x = ০, ১, ২, ৩, ৪-এ সংখ্যাগত derivative হিসাব করুন। কোথায় ০? সেই বিন্দুতে f-এর মান কী? (পরের পাঠের gradient descent এই পর্যবেক্ষণের ওপর দাঁড়িয়ে।)</p></div></details>
